// TH18 v1.00a Stage 6 MainSub06 / GirlRedA01 + GirlA02..A06.
// Source st06.ecl.txt:1307-1335 (MainSub06), 1064-1073 (GirlRedA01),
// 381-446 (GirlA01), 447-517 (GirlA02), 518-588 (GirlA03),
// 589-659 (GirlA04), 660-730 (GirlA05), 731-801 (GirlA06).
// Source schedule per round: A01 at 0, pairs at 90/180/270/360/450, +100 tail.
// Three rounds; I0 starts 32 and grows by 16, used as -192+I0 / 192-I0 for A06.
// Training shell: 120-frame opening buffer; F/MF gates are not re-applied because
// the approved setup fixes this reward wave as the full post-boss formation.

const TIME_LIMIT: int = 3560;      // 120 buffer + 3440 source frames (last E shot + tail)
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;       // source etSprite(0, 5, color)

// Per-bullet EX chain: ANIM a=1 -> position -= 4*initial speed (handled by sh_dist),
// then WAIT(wait_frames), then VELTIME a=100 r=3.2 s=-9999994 (keep entry angle).
xformdef GIRL_ARC(wait_frames: int) {
    wait(wait_frames);
    step_speed(3.2fx, 100 + 65536 * EASE_LINEAR);
}

// Source moveVelTime(mode 1): angle and speed both follow t^2.
sub move_quad_in(start: angle, target: angle, dur: int, s0: fx, s1: fx) {
    var s: int = start as int;
    var d: int = (target as int) - s;
    if d > 32768 { d = d - 65536; }
    if d < -32768 { d = d + 65536; }
    var i: int = 1;
    while i <= dur {
        var u: fx = (i as fx) / (dur as fx);
        var f: fx = u * u;
        var a: angle = (s + (((d as fx) * f) as int)) as angle;
        var v: fx = s0 + (s1 - s0) * f;
        move_vel(0, a, v, EASE_LINEAR);
        wait(1);
        i = i + 1;
    }
}

// Source moveVelTime(mode 7): angle += rate per frame, speed += 0 per frame.
sub move_accum(dir: angle, rate: angle, dur: int, speed: fx) {
    var a: angle = dir;
    var i: int = 0;
    while i < dur {
        a = a + rate;
        move_vel(0, a, speed, EASE_LINEAR);
        wait(1);
        i = i + 1;
    }
}

// Source GirlAxx_at: wait(10), 10 volleys x 10 shots, wait(2) per shot,
// per-shot random offset (RANDRAD, RANDF2*32) then etAngle(RANDF2*2deg, 60deg).
// etAim(0,0) fan; count 1 on E/N and 3 on H/LO.
async sub girl_shots(wait_frames: int, tail: int, ways: int, color: int) {
    wait(10);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, color);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, -2fx);              // ANIM a=1: -4 * 0.5px along own angle
    sh_xform(0, GIRL_ARC(wait_frames));
    var vol: int = 0;
    while vol < 10 {
        var shot: int = 0;
        while shot < 10 {
            var ua: int = rand(65536) - 32768;             // RANDRAD, -pi..pi
            var ud: int = rand(65536) - 32768;             // RANDF2, -1..1
            var dist: fx = ((ud as fx) / 32768) * 32fx;
            var uj: int = rand(65536) - 32768;             // second RANDF2
            var alpha: angle = (((364fx * ((uj as fx) / 32768)) as int)) as angle;
            sh_offset_rad(0, (ua as angle), dist);
            sh_angle(0, alpha, 60deg);
            sh_fire(0);
            wait(2);
            shot = shot + 1;
        }
        wait(tail);
        vol = vol + 1;
    }
}

async sub girl(side: int, kind: int) {
    // Source entries set 24/24 hurtbox and 16/16 hitbox; target radius 12/8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    set_invuln(65535);

    var rank: int = global(GVAR_RANK);
    var color: int = 4;
    var wait_frames: int = 90;
    var tail: int = 60;
    if kind == 0 {
        color = 4;
        wait_frames = 90;
        tail = 60;
    }
    if kind == 1 { color = 6; wait_frames = 60; tail = 60; }
    if kind == 2 { color = 8; wait_frames = 60; tail = 120; }
    if kind == 3 { color = 10; wait_frames = 20; tail = 80; }
    if kind == 4 { color = 13; wait_frames = 20; tail = 80; }
    if kind == 5 { color = 2; wait_frames = 100; tail = 80; }

    if kind == 0 && rank == 0 { tail = 120; }
    if kind == 0 && rank == 2 { wait_frames = 40; }
    if kind == 0 && rank == 3 { wait_frames = 20; tail = 50; }
    if kind == 1 && rank == 0 { tail = 120; }
    if kind == 1 && rank == 3 { tail = 50; }
    if kind == 2 && rank == 0 { tail = 200; }
    if kind == 3 && rank == 0 { tail = 160; }
    if kind == 3 && rank == 3 { tail = 60; }
    if kind == 4 && rank == 0 { tail = 160; }
    if kind == 4 && rank == 3 { tail = 60; }
    if kind == 5 && rank == 0 { tail = 160; }
    if kind == 5 && rank == 3 { tail = 60; }

    var ways: int = 1;
    if rank >= 2 { ways = 3; }

    spawn girl_shots(wait_frames, tail, ways, color);

    var dir: angle = 90deg;
    var target: angle = 0deg;
    var rate: angle = 0deg;
    var speed: fx = 0.8fx;

    if kind == 0 {
        dir = 90deg;
        speed = 0.8fx;
        move_vel(0, dir, speed, EASE_LINEAR);
        wait(180);
        move_quad_in(dir, aim_player(), 120, speed, 1.2fx);
    } else {
        if kind == 1 { dir = 0deg; target = 45deg; speed = 0.8fx; }
        if kind == 2 { dir = -90deg; target = -45deg; speed = 0.8fx; }
        if kind == 3 { dir = 67.5deg; rate = -1deg; speed = 1.4fx; }
        if kind == 4 { dir = -67.5deg; rate = 1deg; speed = 1.4fx; }
        if kind == 5 { dir = 90deg; rate = -1deg; speed = 1.4fx; }
        if side == 1 {
            dir = 180deg - dir;        // enmCreateM mirror: x negated
            rate = 0deg - rate;
            target = 180deg - target;
        }
        move_vel(0, dir, speed, EASE_LINEAR);
        if kind <= 2 {
            wait(180);
            move_quad_in(dir, target, 120, speed, 1.2fx);
        } else {
            wait(120);
            move_accum(dir, rate, 360, speed);
        }
    }
    loop { wait(1000); }
}

// Source MainSub06, 3 rounds. F/MF creation is unconditional here (fixed full wave).
async sub wave() {
    wait(OPENING_BUFFER);
    var i0: int = 32;
    for round in 0..3 {
        _ = spawn_enemy(0fx, -32fx, 500, 0, 1000, 1, girl(0, 0));
        wait(90);
        _ = spawn_enemy(-224fx, 224fx, 500, 0, 1000, 1, girl(0, 1));
        _ = spawn_enemy(224fx, 224fx, 500, 0, 1000, 1, girl(1, 1));
        wait(90);
        _ = spawn_enemy(-160fx, 480fx, 500, 0, 1000, 1, girl(0, 2));
        _ = spawn_enemy(160fx, 480fx, 500, 0, 1000, 1, girl(1, 2));
        wait(90);
        _ = spawn_enemy(-160fx, -32fx, 500, 0, 1000, 1, girl(0, 3));
        _ = spawn_enemy(160fx, -32fx, 500, 0, 1000, 1, girl(1, 3));
        wait(90);
        _ = spawn_enemy(-224fx, 360fx, 500, 0, 1000, 1, girl(0, 4));
        _ = spawn_enemy(224fx, 360fx, 500, 0, 1000, 1, girl(1, 4));
        wait(90);
        var ax: fx = (-192 + i0) as fx;
        _ = spawn_enemy(ax, -32fx, 500, 0, 1000, 1, girl(0, 5));
        _ = spawn_enemy(0fx - ax, -32fx, 500, 0, 1000, 1, girl(1, 5));
        i0 = i0 + 16;
        wait(100);
    }
}

async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
